cases.script:
P=$PWD
/usr/bin/mkfifo "$P/gate"; exec 9<> "$P/gate"
nap() { read -t "${1:-0.05}" -u 9 _junk; }
for n in alpha alphax xalpha beta longnamedprocess1234567890; do /usr/bin/ln -s /usr/bin/sleep "$P/g1$n"; done
declare -A PID
mk() { local tag=$1 name=$2; shift 2; "$P/$name" "${@:-60}" & PID[$tag]=$!; nap 0.03; }
st() { local t out=; for t in "$@"; do if kill -0 "${PID[$t]}" 2>/dev/null; then out+=" $t=alive"; else out+=" $t=dead"; fi; done; echo "state:$out"; }
settle() { local i t any; for ((i=0;i<30;i++)); do any=0; for t in "$@"; do kill -0 "${PID[$t]}" 2>/dev/null && any=1; done; ((any)) || return 0; nap 0.05; done; }
norm() { /usr/bin/sed -E 's/^[^:]*: line [0-9]+: //; s/^(killall|pkill|pgrep): //'; }
reap() { local t; for t in "${!PID[@]}"; do kill -KILL "${PID[$t]}" 2>/dev/null; wait "${PID[$t]}" 2>/dev/null; done; }
trap reap EXIT

mk a1 g1alpha; mk ax g1alphax; mk xa g1xalpha; mk b g1beta; mk l g1longnamedprocess1234567890
killall g1alpha 2>&1 | norm; echo "exact rc=${PIPESTATUS[0]}"; settle a1; st a1 ax xa b l
mk a1 g1alpha
killall g1alpha g1beta g1alpha 2>&1 | norm; echo "multi rc=${PIPESTATUS[0]}"; settle a1 b; st a1 b ax
killall g1longnamedprocess1234567890 2>&1 | norm; echo "long rc=${PIPESTATUS[0]}"; settle l; st l
killall g1nonexistent 2>&1 | norm; echo "nomatch rc=${PIPESTATUS[0]}"
wait "${PID[a1]}"; echo "a1-wait=$?"

