for a in "-HUP" "-SIGUSR1" "-usr1" "-10" "-s HUP" "--signal USR1" "-e" "--exact"; do
  mk x g1alpha; killall $a g1alpha 2>&1 | norm; rc=${PIPESTATUS[0]}
  if [[ $a == -e || $a == --exact ]]; then settle x; fi; settle x; wait "${PID[x]}"; echo "killall $a rc=$rc wait=$?"
done
mk x g1alpha
for a in "--bogus g1alpha" "-s BOGUS g1alpha" "-s 0 g1alpha" "-999 g1alpha" ""; do killall $a 2>&1 | norm | head -1; echo "usage[$a] rc=${PIPESTATUS[0]}"; done
for a in -l -q -w -I -r -g -y -o; do killall $a g1alpha 2>&1 | norm | head -1; echo "opt[$a] rc=${PIPESTATUS[0]}"; done
st x

