killall -u 2000 g1alpha 2>&1 | norm; echo "numeric rc=${PIPESTATUS[0]}"; settle x; st x
mk x g1alpha
me=$(/usr/bin/id -un 2>/dev/null); [[ -n $me ]] && { killall -u "$me" g1alpha 2>&1 | norm; echo "name rc=${PIPESTATUS[0]}"; settle x; st x; } || echo "name skipped"

